"""One token bucket per key (for example per client address)."""

from __future__ import annotations

from ratelimit.bucket import TokenBucket


class Registry:
    """Creates buckets on first use, all with the same capacity and rate."""

    def __init__(self, capacity: float, rate: float) -> None:
        self.capacity = capacity
        self.rate = rate
        self.buckets: dict[str, TokenBucket] = {}

    def allow(self, key: str, tokens: float = 1) -> bool:
        """Whether a request for key may proceed now; takes tokens from its bucket."""
        bucket = self.buckets.get(key)
        if bucket is None:
            bucket = self.buckets[key] = TokenBucket(self.capacity, self.rate)
        return bucket.try_acquire(tokens)

